LoadingSpinner.SPINNER_7CSS_SHEET_B64 = SPINNER_7CSS_SHEET_B64

local cachedSheetAssetId = nil
local triedSheetWrite = false

local function decodeBase64(data)
	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #b do
		map[string.byte(b, i)] = i - 1
	end
	local out = {}
	local n = 0
	local val = 0
	local count = 0
	for i = 1, #data do
		local c = string.byte(data, i)
		local v = map[c]
		if v ~= nil then
			val = val * 64 + v
			count = count + 1
			if count == 4 then
				local b1 = math.floor(val / 65536) % 256
				local b2 = math.floor(val / 256) % 256
				local b3 = val % 256
				n = n + 1
				out[n] = string.char(b1, b2, b3)
				val = 0
				count = 0
			end
		elseif c == 61 then -- "="
			if count == 3 then
				val = val * 64
				local b1 = math.floor(val / 65536) % 256
				local b2 = math.floor(val / 256) % 256
				n = n + 1
				out[n] = string.char(b1, b2)
			elseif count == 2 then
				val = val * 4096
				local b1 = math.floor(val / 65536) % 256
				n = n + 1
				out[n] = string.char(b1)
			end
			break
		end
	end
	return table.concat(out)
end

local function resolve7CssSpinnerSheetAsset()
	if cachedSheetAssetId ~= nil then
		return cachedSheetAssetId
	end
	if triedSheetWrite then
		return nil
	end
	triedSheetWrite = true

	local g = (type(getfenv) == "function" and getfenv()) or _G
	local getAssetFn = (type(getcustomasset) == "function" and getcustomasset)
		or (type(getsynasset) == "function" and getsynasset)
		or (type(g) == "table" and (g.getcustomasset or g.getsynasset))
	local writeFileFn = (type(writefile) == "function" and writefile) or (type(g) == "table" and g.writefile)
	local isFileFn = (type(isfile) == "function" and isfile) or (type(g) == "table" and g.isfile)
	local isFolderFn = (type(isfolder) == "function" and isfolder) or (type(g) == "table" and g.isfolder)
	local makeFolderFn = (type(makefolder) == "function" and makefolder) or (type(g) == "table" and g.makefolder)

	if type(getAssetFn) ~= "function" or type(writeFileFn) ~= "function" then
		return nil
	end

	local filePath = "Win7UI/spinner_aero7_v2.png"
	pcall(function()
		if type(makeFolderFn) == "function" then
			if not (type(isFolderFn) == "function" and isFolderFn("Win7UI")) then
				makeFolderFn("Win7UI")
			end
		end
		local exists = false
		if type(isFileFn) == "function" then
			local okE, resE = pcall(isFileFn, filePath)
			exists = (okE and resE == true)
		end
		if not exists then
			local pngBytes = decodeBase64(SPINNER_7CSS_SHEET_B64)
			writeFileFn(filePath, pngBytes)
		end
		local okA, assetUrl = pcall(getAssetFn, filePath)
		if okA and type(assetUrl) == "string" and assetUrl ~= "" then
			cachedSheetAssetId = assetUrl
		end
	end)

	return cachedSheetAssetId
end

function LoadingSpinner.new(parentContainer, options)
	options = options or {}
	local title = options.Title or options.Text or options.AriaLabel or ""
	-- 7.css gui/_spinner.scss specification: width: 20px; height: 20px;
	local sizePx = tonumber(options.Size) or 20
	local isAnimated = true
	if options.Animate ~= nil then
		isAnimated = (options.Animate == true)
	elseif options.AutoStart ~= nil then
		isAnimated = (options.AutoStart ~= false)
	end
	local speed = tonumber(options.Speed) or 1.0

	local row = Utility.Create("Frame", {
		Name = "LoadingSpinner_" .. (title ~= "" and title or "Loader"),
		Parent = parentContainer,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, math.max(sizePx, 20)),
		LayoutOrder = options.LayoutOrder or (#parentContainer:GetChildren() + 1),
		ZIndex = parentContainer.ZIndex + 1,
	})

	-- 20x20px frame per 7.css gui/_spinner.scss
	local spinnerHolder = Utility.Create("Frame", {
		Name = "SpinnerRingHolder",
		Parent = row,
		AnchorPoint = Vector2.new(0, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(0, sizePx, 0, sizePx),
		ZIndex = row.ZIndex + 1,
	})

	-- 1. Aero Torus Ring 20x20px pixel-matched to spinner.png & spinner.gif
	-- (Pure-UI fallback without getcustomasset; auto-hidden when sprite sheet loads)
	local torusFallback = Utility.Create("Frame", {
		Name = "AeroTorusRing",
		Parent = spinnerHolder,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = spinnerHolder.ZIndex + 1,
	})

	-- 1px outer ring border (y=6 #295377 -> y=16 #276b70 -> y=25 #00c97c from spinner.png)
	local outerRim = Utility.Create("Frame", {
		Name = "OuterBevelRim",
		Parent = torusFallback,
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(1, -2, 1, -2),
		ZIndex = torusFallback.ZIndex + 2,
	})
	Utility.AddCorner(outerRim, 999)
	local outerRimStroke = Utility.AddStroke(outerRim, Color3.fromRGB(255, 255, 255), 1, 0.22, Enum.ApplyStrokeMode.Border)
	local outerRimGrad = Instance.new("UIGradient")
	outerRimGrad.Rotation = 90
	outerRimGrad.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0.00, Color3.fromRGB(41, 83, 119)),  -- #295377
		ColorSequenceKeypoint.new(0.48, Color3.fromRGB(62, 145, 151)), -- #3e9197
		ColorSequenceKeypoint.new(0.52, Color3.fromRGB(39, 107, 112)), -- #276b70
		ColorSequenceKeypoint.new(1.00, Color3.fromRGB(0, 201, 124)),  -- #00c97c
	})
	outerRimGrad.Parent = outerRimStroke

	-- Static 50/50 torus body (r=6..9.5px): upper ice-blue gradient, teal horizon #276b70, lower emerald glow
	local ringThickness = math.max(3, math.floor(sizePx * 0.18 + 0.5))
	local bodyInset = ringThickness + 1
	local torusBody = Utility.Create("Frame", {
		Name = "TorusBodyRing",
		Parent = torusFallback,
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(1, -(bodyInset * 2), 1, -(bodyInset * 2)),
		ZIndex = torusFallback.ZIndex + 1,
	})
	Utility.AddCorner(torusBody, 999)
	local bodyStroke = Utility.AddStroke(torusBody, Color3.fromRGB(255, 255, 255), ringThickness, 0.04, Enum.ApplyStrokeMode.Border)
	local bodyGrad = Instance.new("UIGradient")
	bodyGrad.Rotation = 90
	bodyGrad.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0.00, Color3.fromRGB(201, 241, 255)), -- #c9f1ff (y=7)
		ColorSequenceKeypoint.new(0.20, Color3.fromRGB(175, 213, 243)), -- #afd5f3 (y=8)
		ColorSequenceKeypoint.new(0.44, Color3.fromRGB(147, 189, 214)), -- #93bdd6 (deg=30)
		ColorSequenceKeypoint.new(0.50, Color3.fromRGB(39, 107, 112)),  -- #276b70 (deg=90 50/50 horizon)
		ColorSequenceKeypoint.new(0.62, Color3.fromRGB(41, 118, 120)),  -- #297678 (deg=105)
		ColorSequenceKeypoint.new(0.82, Color3.fromRGB(75, 216, 205)),  -- #4bd8cd (deg=135)
		ColorSequenceKeypoint.new(1.00, Color3.fromRGB(72, 251, 213)),  -- #48fbd5 (y=24)
	})
	bodyGrad.Parent = bodyStroke

	-- 1px inner hole border (r=5.5px: y=10 #59909d -> y=21 #1ac2b4 from spinner.png)
	local innerHoleSize = math.max(8, math.floor(sizePx * 0.55 + 0.5))
	local innerRim = Utility.Create("Frame", {
		Name = "InnerBevelRim",
		Parent = torusFallback,
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(0, innerHoleSize, 0, innerHoleSize),
		ZIndex = torusFallback.ZIndex + 2,
	})
	Utility.AddCorner(innerRim, 999)
	local innerRimStroke = Utility.AddStroke(innerRim, Color3.fromRGB(255, 255, 255), 1, 0.32, Enum.ApplyStrokeMode.Border)
	local innerRimGrad = Instance.new("UIGradient")
	innerRimGrad.Rotation = 90
	innerRimGrad.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0.00, Color3.fromRGB(89, 144, 157)), -- #59909d
		ColorSequenceKeypoint.new(0.50, Color3.fromRGB(39, 107, 112)), -- #276b70
		ColorSequenceKeypoint.new(1.00, Color3.fromRGB(26, 194, 180)), -- #1ac2b4
	})
	innerRimGrad.Parent = innerRimStroke

	-- Cyan-Turquoise comet arc (#cdffff -> #64ffef -> #45b4b3) sweeping across ring (18 steps x 20° per spinner.gif)
	local cometRing = Utility.Create("Frame", {
		Name = "CometHighlightRing",
		Parent = torusFallback,
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(1, -(bodyInset * 2), 1, -(bodyInset * 2)),
		ZIndex = torusFallback.ZIndex + 3,
	})
	Utility.AddCorner(cometRing, 999)
	local cometStroke = Utility.AddStroke(cometRing, Color3.fromRGB(255, 255, 255), ringThickness, 0, Enum.ApplyStrokeMode.Border)
	local cometGrad = Instance.new("UIGradient")
	-- Frame 1 of spinner.png has #cdffff highlight at ~135°
	cometGrad.Rotation = 135
	cometGrad.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0.00, Color3.fromRGB(205, 255, 255)), -- #cdffff (white-cyan peak at deg=240)
		ColorSequenceKeypoint.new(0.22, Color3.fromRGB(100, 255, 239)), -- #64ffef (turquoise halo at deg=180)
		ColorSequenceKeypoint.new(0.45, Color3.fromRGB(69, 180, 179)),  -- #45b4b3 (fade tail at deg=270)
		ColorSequenceKeypoint.new(1.00, Color3.fromRGB(39, 107, 112)),  -- #276b70
	})
	cometGrad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0.00, 0.00),
		NumberSequenceKeypoint.new(0.18, 0.10),
		NumberSequenceKeypoint.new(0.42, 0.62),
		NumberSequenceKeypoint.new(0.62, 1.00),
		NumberSequenceKeypoint.new(1.00, 1.00),
	})
	cometGrad.Parent = cometStroke

	-- 2. ImageLabel displaying 18-frame HD sprite sheet from 7.css
	local sheetAsset = resolve7CssSpinnerSheetAsset()
	local spriteImage = Utility.Create("ImageLabel", {
		Name = "SpinnerSpriteImage",
		Parent = spinnerHolder,
		BackgroundTransparency = 1,
		Image = sheetAsset or "",
		ImageRectOffset = Vector2.new(0, 0),
		ImageRectSize = Vector2.new(FRAME_SIZE, FRAME_SIZE),
		Size = UDim2.new(1, 0, 1, 0),
		Visible = (sheetAsset ~= nil and sheetAsset ~= ""),
		ZIndex = spinnerHolder.ZIndex + 5,
	})
	if sheetAsset ~= nil and sheetAsset ~= "" then
		torusFallback.Visible = false
	end

	local textLabel = nil
	if title ~= "" then
		textLabel = Utility.Create("TextLabel", {
			Name = "SpinnerLabel",
			Parent = row,
			BackgroundTransparency = 1,
			Position = UDim2.new(0, sizePx + 8, 0, 0),
			Size = UDim2.new(1, -(sizePx + 8), 1, 0),
			Font = Theme.Fonts.Regular,
			Text = title,
			TextColor3 = Theme.Colors.TextPrimary,
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = row.ZIndex + 1,
		})
	end

	local running = false
	local frameIndex = 1 -- 1..18 frames per gui/icon/spinner.gif

	local function applyFrame(idx)
		frameIndex = ((idx - 1) % TOTAL_FRAMES) + 1
		local col = (frameIndex - 1) % FRAME_COLS
		local row = math.floor((frameIndex - 1) / FRAME_COLS)
		spriteImage.ImageRectOffset = Vector2.new(col * FRAME_SIZE, row * FRAME_SIZE)
		cometGrad.Rotation = (135 + (frameIndex - 1) * 20) % 360
	end

	applyFrame(1)

	local controller = {
		Row = row,
		Holder = spinnerHolder,
		TorusRing = torusFallback,
		SpriteImage = spriteImage,
		Label = textLabel,
		IsRunning = false,
	}

	function controller:Start()
		if running then
			return
		end
		running = true
		self.IsRunning = true
		spinnerHolder.Visible = true

		if task and task.spawn then
			task.spawn(function()
				while running and spinnerHolder and spinnerHolder.Parent do
					applyFrame(frameIndex + 1)
					if task.wait then
						task.wait(0.05 / math.max(0.1, speed))
					else
						break
					end
				end
			end)
		end
	end

	function controller:Stop()
		running = false
		self.IsRunning = false
		applyFrame(1)
	end

	function controller:SetAnimate(animateEnabled)
		if animateEnabled then
			self:Start()
		else
			self:Stop()
		end
	end

	function controller:SetText(newText)
		if textLabel then
			textLabel.Text = tostring(newText or "")
		end
	end

	function controller:SetVisible(vis)
		row.Visible = (vis == true)
	end

	if isAnimated then
		controller:Start()
	end

	return controller
end

return LoadingSpinner
